llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C46"],
      "claim": "Nilotinib, a close aminopyrimidine-aniline kinase inhibitor analogue with high transferability, has an absolute oral bioavailability of 31% in fasted humans, directly supporting F ≥ 20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C59"],
      "claim": "GSK1322322, a high-transfer analogue with a basic amine/pyrimidine/aniline scaffold, showed 77% absolute oral bioavailability after a meal in healthy volunteers, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Brigatinib, another high-transfer aminopyrimidine-based kinase inhibitor, had approximately 46% oral bioavailability in healthy volunteers, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Clomipramine, a moderate-transfer lipophilic basic amine drug, has about 50% oral bioavailability, showing that strongly basic ionizable amines can still achieve high systemic exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C41"],
      "claim": "Encainide, a moderate-transfer basic amine drug with an aromatic methoxy group, has a mean oral bioavailability of about 30% in healthy subjects, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Nilotinib at 400 mg showed a calculated bioavailability of 17% in patients, a contradictory dose-dependent low value, but this is outweighed by the 31% absolute estimate and other high-F analogues.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C11"],
      "claim": "Remimazolam, a low-transfer benzodiazepine, has very low oral bioavailability of 1.2%, but its structural dissimilarity and low transferability make it a weak contradictory example.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is osimertinib, an oral EGFR inhibitor. The highest-transfer experimental analogues are structurally related aminopyrimidine-aniline kinase inhibitors with measured human absolute bioavailability mostly ≥30% (nilotinib ~31%, brigatinib ~46%, GSK1322322 57-77%). Lower-transfer low-F examples such as remimazolam and alprenolol are structurally dissimilar and do not override this pattern. The physicochemical low-absorption prior is therefore overridden by transferable human bioavailability data.",
  "evidence_gaps": [
    "No direct absolute-bioavailability record for the query molecule itself is included in the supplied evidence; inference relies on close kinase-inhibitor analogues.",
    "Nilotinib bioavailability data straddle the 20% threshold and are dose-dependent, introducing some uncertainty in exact F extrapolation.",
    "Transporter-mediated efflux and metabolic clearance of the query are not directly measured in the supplied evidence."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

